    /// <summary>
    /// Shining Force CD item names depend on the book. The call order below is
    /// identical to the original editor so collisions resolve the same way:
    /// <c>Add</c> keeps the first name for an id; <c>AddWithBase</c> also maps an
    /// equipped (0x80) id onto its base id, overwriting.
    /// <paramref name="bookGroup"/>: 1 = Books 1–2, 2 = Books 3–4, 0 = unknown (common names only).
    /// </summary>
    public static Dictionary<byte, string> BuildShiningForceCDItems(int bookGroup, Action<string>? log = null)
    {
        var map = new Dictionary<byte, string>();

        void Add(string name, int raw)
        {
            byte id = (byte)raw;
            if (map.TryGetValue(id, out var existing))
            {
                if (existing != name)
                {
                    log?.Invoke($"[SFCD] Item ID collision 0x{id:X2}: '{existing}' vs '{name}'");
                }

                return;
            }

            map[id] = name;
        }

        void AddWithBase(string name, int raw)
        {
            Add(name, raw);
            if ((raw & 0x80) != 0)
            {
                map[(byte)(raw & 0x7F)] = name;
            }
        }

        // Common to every book.
        Add("Medical Herb", 0x00);
        Add("Healing Seed", 0x01);
        Add("Antidote", 0x02);
        Add("Healing Rain", 0x03);
        Add("Angel Wing", 0x04);
        Add("Powerful Wine", 0x05);
        Add("Protect Milk", 0x06);
        Add("Quick Chicken", 0x07);
        Add("Running Pimento", 0x08);
        Add("Cheerful Bread", 0x09);
        AddWithBase("Power Ring", 0x0A);
        AddWithBase("Protect Ring", 0x0B);
        AddWithBase("Quick Ring", 0x0C);
        AddWithBase("Running Ring", 0x0D);
        AddWithBase("White Ring", 0x0E);
        AddWithBase("Black Ring", 0x0F);
        AddWithBase("Evil Ring", 0x90);
        Add("Empty", 0x7F);
        AddWithBase("Empty (Equipped?)", 0xFF);

        if (bookGroup == 1)
        {
            // Books 1 & 2.
            AddWithBase("Leather Glove", 0x91);
            AddWithBase("Power Glove", 0x92);
            AddWithBase("Battle Glove", 0x93);
            AddWithBase("Iron Claw", 0x94);
            AddWithBase("Short Sword", 0x9D);
            AddWithBase("Broad Sword", 0xA1);
            AddWithBase("Critical Sword", 0xA2);
            AddWithBase("Wooden Stick", 0xA3);
            AddWithBase("Robin's Arrow", 0xA4);
            AddWithBase("Dark Sword", 0xA5);
            AddWithBase("Wood Sword", 0x26);
            AddWithBase("Sword of Hajya", 0xA7);
            AddWithBase("Bronze Lance", 0xA8);
            AddWithBase("Steel Lance", 0xA9);
            AddWithBase("Chrome Lance", 0xAA);
            AddWithBase("Evil Lance", 0xAB);
            AddWithBase("Halberd", 0xAC);
            AddWithBase("Spear", 0xAD);
            AddWithBase("Power Spear", 0xAE);
            AddWithBase("Valkyrie", 0xAF);
            AddWithBase("Hand Axe", 0xB0);
            AddWithBase("Middle Axe", 0xB1);
            AddWithBase("Battle Axe", 0xB2);
            AddWithBase("Heat Axe", 0xB3);
            AddWithBase("Axe of Atlas", 0xB4);
            AddWithBase("Wooden Staff", 0xB5);
            AddWithBase("Protect Staff", 0xB6);
            AddWithBase("Holy Staff", 0xB7);
            AddWithBase("Power Stick", 0xB8);
            AddWithBase("Demon Rod", 0xB9);
            AddWithBase("Flail", 0xBA);
            AddWithBase("Wooden Arrow", 0xBB);
            AddWithBase("Steel Arrow", 0xBC);
            AddWithBase("Assault Shell", 0xBD);
            AddWithBase("Buster Shot", 0xBE);
            AddWithBase("Short Axe", 0x97);
            AddWithBase("Bronze Rod", 0x98);
            AddWithBase("Iron Rod", 0x99);
            AddWithBase("Iron Arrow", 0x9A);
            AddWithBase("Club", 0x15);
            AddWithBase("Club", 0x95);
            AddWithBase("Steel Sword", 0xA0);
            AddWithBase("Steel Sword", 0x20);
        }
        else if (bookGroup == 2)
        {
            // Books 3 & 4.
            AddWithBase("Misty Knuckle", 0x91);
            AddWithBase("Giant Knuckle", 0x92);
            AddWithBase("Large Axe", 0x93);
            AddWithBase("Earth Axe", 0x94);
            AddWithBase("Great Rod", 0x95);
            AddWithBase("Mystery Staff", 0x96);
            AddWithBase("Hyper Cannon", 0x97);
            AddWithBase("Shut Cannon", 0x98);
            AddWithBase("Buster Sword", 0x99);
            AddWithBase("Counter Sword", 0x9A);
            AddWithBase("Light Sword", 0x26);
            AddWithBase("Javelin", 0x9B);
            AddWithBase("Chrome Lance", 0x9C);
            AddWithBase("Samurai Sword", 0x9D);
            AddWithBase("Higins", 0x9E);
            AddWithBase("Murasame", 0x9F);
            AddWithBase("Murasana", 0xA0);
            AddWithBase("Iris Blade", 0xA1);
            AddWithBase("Kamikaze Axe", 0xA2);
            AddWithBase("Kizer Knuckle", 0xA3);
            AddWithBase("Venom Javelin", 0xA4);
            AddWithBase("Work Glove", 0xA5);
